package pgbench

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"testing"

	"github.com/stretchr/testify/require"
)

// Same four durable operations as the Kafka consumer's persist method. Bind
// values are integers generated by this test, and the two dialects differ only
// in placeholder spelling and duplicate-receipt handling.
func persist(ctx context.Context, x target, id int64) error {
	my := []string{
		"INSERT IGNORE INTO bench_receipt(order_id) VALUES (?)",
		"INSERT INTO bench_order(id,user_id,voucher_id,status) VALUES (?,?,1,1)",
		"INSERT INTO bench_notice(event_key,user_id,content) VALUES(?,?,?)",
	}
	pg := []string{
		"INSERT INTO bench_receipt(order_id) VALUES ($1) ON CONFLICT(order_id) DO NOTHING",
		"INSERT INTO bench_order(id,user_id,voucher_id,status) VALUES ($1,$2,1,1)",
		"INSERT INTO bench_notice(event_key,user_id,content) VALUES($1,$2,$3)",
	}
	query := my
	if x.name == "pg" {
		query = pg
	}
	tx, err := x.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()
	r, err := tx.ExecContext(ctx, query[0], id)
	if err != nil {
		return err
	}
	n, err := r.RowsAffected()
	if err != nil {
		return err
	}
	if n == 0 {
		return tx.Commit()
	}
	if _, err = tx.ExecContext(ctx, query[1], id, id); err != nil {
		return err
	}
	r, err = tx.ExecContext(ctx, seatSQL)
	if err != nil {
		return err
	}
	n, err = r.RowsAffected()
	if err != nil {
		return err
	}
	if n != 1 {
		return errSoldOut
	}
	_, err = tx.ExecContext(ctx, query[2], fmt.Sprintf("order:%d", id), id, "优惠券订单已生成")
	if err != nil {
		return err
	}
	return tx.Commit()
}

var errSoldOut = errors.New("sold out")

func resetOrders(t *testing.T, db *sql.DB, count int) {
	t.Helper()
	for _, name := range []string{"bench_receipt", "bench_order", "bench_notice"} {
		exec(t, db, "DELETE FROM "+name)
	}
	exec(t, db, fmt.Sprintf("UPDATE bench_slot SET remaining=%d WHERE id=1", count))
}
func verifyOrders(t *testing.T, ctx context.Context, x target, count int) {
	t.Helper()
	require.NoError(t, persist(ctx, x, 1))
	require.ErrorIs(t, persist(ctx, x, int64(count+1)), errSoldOut)
	for _, name := range []string{"bench_receipt", "bench_order", "bench_notice"} {
		var n int
		require.NoError(t, x.db.QueryRow("SELECT COUNT(*) FROM "+name).Scan(&n))
		require.Equal(t, count, n)
	}
	var remaining int
	require.NoError(t, x.db.QueryRow("SELECT remaining FROM bench_slot WHERE id=1").Scan(&remaining))
	require.Zero(t, remaining)
}
